	L["If checked, boat harbors, zepplin towers and tram stations will be shown."] = "Wenn ausgewählt, werden Bootshäfen, Zeppelintürme und Bahnstationen angezeigt."
	L["If checked, continent and zone menus will be shown in the map title bar.|n|nThe menus cannot be used in combat."] = "Wenn ausgewählt, werden in der Titelleiste der Karte Menüs für Kontinente und Gebiete angezeigt.|n|nDie Menüs können im Kampf nicht verwendet werden."
