	L["If checked, boat harbors, zepplin towers and tram stations will be shown."] = "Se selezionato, verranno mostrati i porti, le torri degli zeppelin e le stazioni del tram."
	L["If checked, continent and zone menus will be shown in the map title bar.|n|nThe menus cannot be used in combat."] = "Se selezionato, i menu dei continenti e delle zone verranno mostrati nella barra del titolo della mappa.|n|nI menu non possono essere usati in combattimento."
	L["If checked, coordinates will be shown."] = "Se selezionato, verranno mostrate le coordinate."
	L["If checked, coordinates will have a dark background texture."] = "Se selezionata, le coordinate avranno una texture di sfondo scura."
	L["If checked, dungeons and raids will be shown."] = "Se selezionato, verranno mostrate le spedizioni e incursioni."
	L["If checked, flight points will be shown."] = "Se selezionato, verranno mostrati i punti di volo."
	L["If checked, points of interest belonging to the opposing faction will be shown.|n|nThis applies to flight points, boats, zeppelins and trams, and portals."] = "Se selezionato, verranno mostrati i punti d'interesse della fazione avversaria.|n|nQuesto vale per i punti di volo, le navi, gli zeppelin e i tram, e i portali."
	L["If checked, points of interest will be shown."] = "Se selezionato, verranno mostrati i punti d'interesse."
	L["If checked, portals will be shown."] = "Se selezionato, verranno mostrati i portali."
	L["If checked, spirit healers will be shown."] = "Se selezionato, verranno mostrati gli Spiriti Guaritori."
	L["If checked, the battlefield map will stay centered on your location as long as you are not in a dungeon.|n|nYou can hold shift while panning the map to temporarily prevent it from centering."] = "Se selezionato, la mappa del campo di battaglia rimarrà centrata sulla tua posizione finché non ti trovi in ​​una spedizione.|n|nPuoi tenere premuto Maiusc mentre esegui la panoramica della mappa per impedirne temporaneamente il centraggio."
	L["If checked, the blackout frame will be hidden."] = "Se selezionato, il frame di oscuramento verrà nascosto."
	L["If checked, the map will not fade while your character is moving."] = "Se selezionato, la mappa non svanirà mentre il tuo personaggio si muove."
	L["If checked, the map will show a map of the dungeon or raid you are in, with bosses, entrances and level changes.|n|nUse the mouse wheel to zoom and drag to pan.|n|nRight-click the dungeon map to show the normal map until you next open the map."] = "Se selezionato, la mappa mostrerà una mappa della spedizione o dell'incursione in cui ti trovi, con boss, ingressi e cambi di livello.|n|nUsa la rotella del mouse per ingrandire e trascina per spostare la mappa.|n|nClicca col tasto destro sulla mappa della spedizione per mostrare la mappa normale fino alla prossima apertura della mappa."
	L["If checked, the map will use a simple frame with a compact title bar."] = "Se selezionato, la mappa utilizzerà un frame semplice con una barra del titolo compatta."
	L["If checked, the minimap button will be shown."] = "Se selezionato, verrà mostrato il pulsante della minimappa."
	L["If checked, the minimum fishing skill levels will be shown."] = "Se selezionato, verranno mostrati i livelli minimi di competenza in Pesca."
	L["If checked, the world map filter reset button will be hidden."] = "Se selezionato, il pulsante di reimpostazione del filtro della mappa del mondo verrà nascosto."
	L["If checked, town and city icons will not be shown on the continent maps."] = "Se selezionato, le icone dei paesi e delle città non verranno visualizzate sulle mappe dei continenti."
	L["If checked, unexplored areas of the map will be shown on the world map and the battlefield map."] = "Se selezionato, le aree inesplorate della mappa verranno mostrate sulla mappa del mondo e sulla mappa del campo di battaglia."
	L["If checked, unexplored areas will be tinted."] = "Se selezionato, le aree inesplorate verranno colorate."
	L["If checked, you can move the battlefield map by dragging any of its borders."] = "Se selezionato, puoi spostare la mappa del campo di battaglia trascinando uno qualsiasi dei suoi bordi."
	L["If checked, you will be able to customise the battlefield map."] = "Se selezionato, sarai in grado di personalizzare la mappa del campo di battaglia."
	L["If checked, you will be able to move the frame by dragging the border."] = "Se selezionato, sarai in grado di spostare il frame trascinando il bordo."
	L["If checked, you will be able to move the map.|n|nThe map position will be saved separately for the maximised and windowed maps."] = "Se selezionato, sarai in grado di spostare la mappa.|n|nLa posizione della mappa verrà salvata separatamente per le mappe ingrandite e in finestra."
	L["If checked, you will be able to scale the map."] = "Se selezionato, sarai in grado di ridimensionare la mappa."
	L["If checked, zone crossings will be shown.|n|nThese are arrows that indicate the zone exit pathways."] = "Se selezionato, verranno mostrati gli attraversamenti di zona.|n|nSono frecce che indicano i percorsi d'uscita dalla zona."
	L["If checked, zone levels will be shown on the continent maps."] = "Se selezionato, i livelli delle zone verranno mostrati sulle mappe dei continenti."
