	L["If checked, boat harbors, zepplin towers and tram stations will be shown."] = "항구, 비행선 탑, 지하철 역이 표시됩니다."
	L["If checked, continent and zone menus will be shown in the map title bar.|n|nThe menus cannot be used in combat."] = "지도 제목 표시줄에 대륙 및 지역 메뉴가 표시됩니다.|n|n전투 중에는 메뉴를 사용할 수 없습니다."
