	L["If checked, points of interest belonging to the opposing faction will be shown.|n|nThis applies to flight points, boats, zeppelins and trams, and portals."] = "상대 진영에 속한 관심 지점이 표시됩니다.|n|n비행 지점, 여객선, 비행선, 지하철 및 포탈에 적용됩니다."
	L["If checked, points of interest will be shown."] = "관심 지점이 표시됩니다."
	L["If checked, portals will be shown."] = "포탈이 표시됩니다."
	L["If checked, spirit healers will be shown."] = "영혼의 치유사가 표시됩니다."
	L["If checked, the battlefield map will stay centered on your location as long as you are not in a dungeon.|n|nYou can hold shift while panning the map to temporarily prevent it from centering."] = "던전에 있지 않은 한 전장 지도가 항상 플레이어 위치 중심으로 유지됩니다.|n|n지도를 이동할 때 Shift 키를 누르고 있으면 일시적으로 중심 유지 기능을 해제할 수 있습니다."
	L["If checked, the blackout frame will be hidden."] = "배경 어둡게 하기 프레임이 숨겨집니다."
	L["If checked, the map will not fade while your character is moving."] = "캐릭터가 이동 중일 때 지도가 흐려지지 않습니다."
	L["If checked, the map will show a map of the dungeon or raid you are in, with bosses, entrances and level changes.|n|nUse the mouse wheel to zoom and drag to pan.|n|nRight-click the dungeon map to show the normal map until you next open the map."] = "현재 있는 던전이나 공격대의 지도가 우두머리, 입구, 층 이동 지점과 함께 표시됩니다.|n|n마우스 휠로 확대하고 드래그하여 이동합니다.|n|n던전 지도를 우클릭하면 다음에 지도를 열 때까지 일반 지도가 표시됩니다."
	L["If checked, the map will use a simple frame with a compact title bar."] = "지도에 간결한 제목 표시줄이 있는 단순한 프레임이 사용됩니다."
	L["If checked, the minimap button will be shown."] = "미니맵 버튼이 표시됩니다."
	L["If checked, the minimum fishing skill levels will be shown."] = "최소 낚시 숙련도가 표시됩니다."
	L["If checked, the world map filter reset button will be hidden."] = "세계 지도 필터 재설정 버튼이 숨겨집니다."
	L["If checked, town and city icons will not be shown on the continent maps."] = "대륙 지도에 마을 및 도시 아이콘이 표시되지 않습니다."
	L["If checked, unexplored areas of the map will be shown on the world map and the battlefield map."] = "지도에서 탐험되지 않은 지역이 세계 지도와 전장 지도에 표시됩니다."
	L["If checked, unexplored areas will be tinted."] = "탐험하지 않은 지역은 음영 처리됩니다."
	L["If checked, you can move the battlefield map by dragging any of its borders."] = "전장 지도의 가장자리를 드래그하여 이동할 수 있습니다."
	L["If checked, you will be able to customise the battlefield map."] = "전장 지도를 사용자 정의할 수 있습니다."
	L["If checked, you will be able to move the frame by dragging the border."] = "테두리를 드래그하여 프레임을 이동할 수 있습니다."
	L["If checked, you will be able to move the map.|n|nThe map position will be saved separately for the maximised and windowed maps."] = "지도를 이동할 수 있습니다.|n|n최대화 상태와 창 모드 상태의 지도 위치는 각각 별도로 저장됩니다."
